using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool implementations ---
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchWebAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Build the chat client through MEAI ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Create the agent using Microsoft Agent Framework ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic, you:
        1. Search the web for relevant information using multiple queries.
        2. Save key findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and
           produce a well-structured summary with sources.
        Always cite the URLs where you found information.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Get the research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided. Exiting.");
    return 1;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent ---
var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine();
return 0;

// --- Web Search Tool ---

partial class WebSearcher
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    static WebSearcher()
    {
        s_httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
    }

    [Description("Searches the web for the given query and returns a list of result snippets with URLs. "
        + "Use specific, targeted queries for best results.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web.")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            var html = await s_httpClient.GetStringAsync(url);
            var results = ParseDuckDuckGoLite(html);

            if (results.Count == 0)
            {
                return $"No results found for: {query}";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}");
            sb.AppendLine();

            foreach (var (title, snippet, link) in results.Take(5))
            {
                sb.AppendLine($"Title: {title}");
                sb.AppendLine($"URL: {link}");
                sb.AppendLine($"Snippet: {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Url)> ParseDuckDuckGoLite(string html)
    {
        var results = new List<(string, string, string)>();

        // Extract result links
        var linkMatches = LinkPattern().Matches(html);
        var snippetMatches = SnippetPattern().Matches(html);

        for (var i = 0; i < linkMatches.Count && i < 5; i++)
        {
            var title = StripHtml(linkMatches[i].Groups[2].Value).Trim();
            var url = linkMatches[i].Groups[1].Value.Trim();
            var snippet = i < snippetMatches.Count
                ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
                : "(no snippet)";

            if (!string.IsNullOrWhiteSpace(title) && url.StartsWith("http", StringComparison.Ordinal))
            {
                results.Add((title, snippet, url));
            }
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTagPattern().Replace(html, " ");
        text = WebUtility.HtmlDecode(text);
        return WhitespacePattern().Replace(text, " ").Trim();
    }

    [GeneratedRegex("""<a[^>]+href="(https?://[^"]+)"[^>]*>(.*?)</a>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex LinkPattern();

    [GeneratedRegex("""<td class="result-snippet">(.*?)</td>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex SnippetPattern();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagPattern();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespacePattern();
}

// --- Note-taking Tool ---

class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note. Use this to record key findings, facts, or quotes "
        + "discovered during research. Include the source URL when available.")]
    public string AddNote(
        [Description("The note content to save, including source URL if applicable.")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all saved research notes. Call this before writing your final summary "
        + "to review everything you've gathered.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"All research notes ({_notes.Count} total):");
        sb.AppendLine();

        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note #{i + 1} ---");
            sb.AppendLine(_notes[i]);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

